function sql(database, statement) {
  return execFileSync(mysqlExe, [...mysqlArgs, database, "-e", statement], { encoding: "utf8", windowsHide: true, maxBuffer: 50 * 1024 * 1024 }).trim();
}
function mysqlFromStdin(executable,args,statement,timeoutMs=0){
  return new Promise((resolve,reject)=>{
    const child=spawn(executable,args,{windowsHide:true,stdio:['pipe','pipe','pipe']}),chunks=[],errors=[];let size=0,settled=false;
    const fail=error=>{if(settled)return;settled=true;reject(error)};
    const timer=timeoutMs?setTimeout(()=>{child.kill();fail(new Error('Query timed out. Try a more specific filter.'))},timeoutMs):null;
    child.on('error',error=>{clearTimeout(timer);fail(error)});
    child.stdout.on('data',chunk=>{size+=chunk.length;if(size>50*1024*1024){child.kill();fail(new Error('MySQL output exceeded 50 MB.'))}else chunks.push(chunk)});
    child.stderr.on('data',chunk=>errors.push(chunk));
    child.on('close',code=>{clearTimeout(timer);if(settled)return;settled=true;const stderr=Buffer.concat(errors).toString('utf8').trim();if(code!==0)return reject(new Error(stderr||`MySQL exited with code ${code}.`));resolve(Buffer.concat(chunks).toString('utf8').trim())});
    child.stdin.on('error',error=>{if(error.code!=='EPIPE')fail(error)});
    child.stdin.end(statement);
  });
}
async function sqlAsync(database, statement) {
  return mysqlFromStdin(mysqlExe,[...mysqlArgs,database],statement);
}
async function auditSqlAsync(statement){return mysqlFromStdin(auditExe,auditMysqlArgs,statement)}
async function membershipSqlAsync(database,statement){return mysqlFromStdin(membershipExe,[...membershipMysqlArgs,database],statement)}
function parse(output, keys) {
  if (!output) return [];
  return output.split(/\r?\n/).map((line) => Object.fromEntries(line.split("\t").map((value, index) => [keys[index], value === "NULL" ? "" : value])));
}
const num = (row, keys) => { for (const key of keys) row[key] = Number(row[key]); return row; };
const monthList = months.map((month) => `'${month}'`).join(",");

async function areaAddress(database,_reportMonths,_billMonth,connStatus='all') {
  const statusWhere=connStatus==='all'?'':` WHERE ConnStatus='${connStatus}'`;
  const statement=`SELECT COALESCE(NULLIF(TRIM(Area), ''), 'UNKNOWN'), COUNT(*), COUNT(NULLIF(TRIM(Address), '')), COUNT(DISTINCT NULLIF(TRIM(Address), '')) FROM master${statusWhere} GROUP BY COALESCE(NULLIF(TRIM(Area), ''), 'UNKNOWN') ORDER BY COUNT(*) DESC, 1;`;
  const selected=database==='all'?databases:databases.filter(item=>item.database===database);
  const groups=await Promise.all(selected.map(async(item)=>parse(await sqlAsync(item.database,statement),["area","consumers","withAddress","distinctAddresses"]).map(row=>({database:item.label,...num(row,["consumers","withAddress","distinctAddresses"])}))));
  const rows=groups.flat();
  const consumers = rows.reduce((sum, row) => sum + row.consumers, 0), addressed = rows.reduce((sum, row) => sum + row.withAddress, 0);
  rows.forEach((row) => { row.coverage = row.consumers ? row.withAddress / row.consumers : 0; row.share = consumers ? row.consumers / consumers : 0; });
  const columns=database==='all'?[["database","Office","text"],["area","Area","text"],["consumers","Consumers","number"],["withAddress","With address","number"],["distinctAddresses","Distinct addresses","number"],["coverage","Coverage","percent"],["share","Share of all 4","percent"]]:[["area","Area","text"],["consumers","Consumers","number"],["withAddress","With address","number"],["distinctAddresses","Distinct addresses","number"],["coverage","Coverage","percent"],["share","Share of DB","percent"]];
  return { columns, metrics: [["Service area rows",rows.length,"number"],["Total consumers",consumers,"number"],["With address",addressed,"number"],["Address coverage",consumers ? addressed/consumers : 0,"percent"]], rows };
}

function monthlyGrowth(database) {
  const statement = "SELECT billmonth, SUM(cnt), SUM(kwh), SUM(bill) FROM (SELECT billmonth, COUNT(entry) cnt, COALESCE(SUM(KilowattHour),0) kwh, COALESCE(SUM(TotalBill),0) bill FROM billhistory GROUP BY billmonth UNION ALL SELECT billmonth, COUNT(entry), COALESCE(SUM(KilowattHour),0), COALESCE(SUM(TotalBill),0) FROM billhistory_bm GROUP BY billmonth) x GROUP BY billmonth ORDER BY billmonth;";
  const rows = parse(sql(database, statement), ["month","consumers","kwh","totalBill"]).map((r) => num(r,["consumers","kwh","totalBill"]));
  rows.forEach((row,index) => { const prev=rows[index-1]; row.consumerGrowth=prev?.consumers ? (row.consumers-prev.consumers)/prev.consumers : null; row.kwhGrowth=prev?.kwh ? (row.kwh-prev.kwh)/prev.kwh : null; row.billGrowth=prev?.totalBill ? (row.totalBill-prev.totalBill)/prev.totalBill : null; });
  const latest=rows.at(-1) ?? {};
  return { columns:[["month","Month","month"],["consumers","Consumers","number"],["kwh","kWh sales","decimal"],["totalBill","Total bill","currency"],["consumerGrowth","Consumer growth","percent"],["kwhGrowth","kWh growth","percent"],["billGrowth","Bill growth","percent"]], metrics:[["Months available",rows.length,"number"],["Latest consumers",latest.consumers??0,"number"],["Latest kWh",latest.kwh??0,"decimal"],["Latest total bill",latest.totalBill??0,"currency"]], rows };
}

async function collection(database, reportMonths=3) {
  const available=parse(await sqlAsync(database,`SELECT BillMonth FROM (SELECT BillMonth FROM billhistory UNION SELECT BillMonth FROM billhistory_bm) m WHERE BillMonth REGEXP '^[0-9]{4}$' AND LEFT(BillMonth,2) BETWEEN '01' AND '12' GROUP BY BillMonth ORDER BY CAST(CONCAT('20',RIGHT(BillMonth,2),LEFT(BillMonth,2)) AS UNSIGNED) DESC LIMIT ${reportMonths}`),['month']).map(row=>row.month);
  const selectedMonthList=(available.length?available:months.slice(0,reportMonths)).map(month=>`'${month}'`).join(',');
  const statement=`SELECT billmonth, ratecode, SUM(cnt), SUM(kwh), SUM(bill), SUM(paid_count), SUM(paid_kwh), SUM(paid_bill), SUM(unpaid_count), SUM(unpaid_kwh), SUM(unpaid_bill) FROM (SELECT billmonth, COALESCE(ratecode,'') ratecode, COUNT(entry) cnt, COALESCE(SUM(KilowattHour),0) kwh, COALESCE(SUM(TotalBill),0) bill, SUM(flag_paid='Y') paid_count, COALESCE(SUM(IF(flag_paid='Y',KilowattHour,0)),0) paid_kwh, COALESCE(SUM(IF(flag_paid='Y',TotalBill,0)),0) paid_bill, SUM(flag_paid='N') unpaid_count, COALESCE(SUM(IF(flag_paid='N',KilowattHour,0)),0) unpaid_kwh, COALESCE(SUM(IF(flag_paid='N',TotalBill,0)),0) unpaid_bill FROM billhistory WHERE billmonth IN (${selectedMonthList}) GROUP BY billmonth,ratecode UNION ALL SELECT billmonth, COALESCE(ratecode,''), COUNT(entry), COALESCE(SUM(KilowattHour),0), COALESCE(SUM(TotalBill),0), SUM(flag_paid='Y'), COALESCE(SUM(IF(flag_paid='Y',KilowattHour,0)),0), COALESCE(SUM(IF(flag_paid='Y',TotalBill,0)),0) paid_bill, SUM(flag_paid='N'), COALESCE(SUM(IF(flag_paid='N',KilowattHour,0)),0), COALESCE(SUM(IF(flag_paid='N',TotalBill,0)),0) FROM billhistory_bm WHERE billmonth IN (${selectedMonthList}) GROUP BY billmonth,ratecode) x GROUP BY billmonth,ratecode ORDER BY CAST(CONCAT('20',RIGHT(billmonth,2),LEFT(billmonth,2)) AS UNSIGNED) DESC,ratecode;`;
  const numeric=["consumers","kwh","totalBill","paidConsumers","paidKwh","paidBill","unpaidConsumers","unpaidKwh","unpaidBill"];
  const rows=parse(sql(database,statement),["month","rateCode",...numeric]).map((r)=>num(r,numeric)); rows.forEach((r)=>r.collectionRate=r.totalBill?r.paidBill/r.totalBill:0);
  const totalBill=rows.reduce((s,r)=>s+r.totalBill,0),paid=rows.reduce((s,r)=>s+r.paidBill,0);
  return { columns:[["month","Month","month"],["rateCode","Rate code","text"],["consumers","Consumers","number"],["kwh","kWh","decimal"],["totalBill","Total bill","currency"],["paidConsumers","Paid count","number"],["paidBill","Paid bill","currency"],["unpaidConsumers","Unpaid count","number"],["unpaidBill","Unpaid bill","currency"],["collectionRate","Collection rate","percent"]], metrics:[["Report months",available.length,"number"],["Total billed",totalBill,"currency"],["Paid amount",paid,"currency"],["Collection rate",totalBill?paid/totalBill:0,"percent"]], rows, reportMonths:available };
}

function areaBilling(database,_reportMonths,billMonth='') {
  const selectedMonthList=billMonth?`'${billMonth}'`:monthList;
  const statement=`SELECT billmonth, COALESCE(NULLIF(TRIM(Area),''),'UNKNOWN'), SUM(cnt), SUM(kwh), SUM(bill), SUM(paid), SUM(unpaid) FROM (SELECT billmonth,Area,COUNT(entry) cnt,COALESCE(SUM(KilowattHour),0) kwh,COALESCE(SUM(TotalBill),0) bill,COALESCE(SUM(IF(flag_paid='Y',TotalBill,0)),0) paid,COALESCE(SUM(IF(flag_paid='N',TotalBill,0)),0) unpaid FROM billhistory WHERE billmonth IN (${selectedMonthList}) GROUP BY billmonth,Area UNION ALL SELECT billmonth,Area,COUNT(entry),COALESCE(SUM(KilowattHour),0),COALESCE(SUM(TotalBill),0),COALESCE(SUM(IF(flag_paid='Y',TotalBill,0)),0),COALESCE(SUM(IF(flag_paid='N',TotalBill,0)),0) FROM billhistory_bm WHERE billmonth IN (${selectedMonthList}) GROUP BY billmonth,Area) x GROUP BY billmonth,Area ORDER BY billmonth DESC,Area;`;
  const keys=["month","area","consumers","kwh","totalBill","paidBill","unpaidBill"], rows=parse(sql(database,statement),keys).map((r)=>num(r,keys.slice(2))); rows.forEach((r)=>r.collectionRate=r.totalBill?r.paidBill/r.totalBill:0);
  return { columns:[["month","Month","month"],["area","Area","text"],["consumers","Consumers","number"],["kwh","kWh","decimal"],["totalBill","Total bill","currency"],["paidBill","Paid bill","currency"],["unpaidBill","Unpaid bill","currency"],["collectionRate","Collection rate","percent"]], metrics:[["Rows",rows.length,"number"],["Consumers",rows.reduce((s,r)=>s+r.consumers,0),"number"],["kWh",rows.reduce((s,r)=>s+r.kwh,0),"decimal"],["Total billed",rows.reduce((s,r)=>s+r.totalBill,0),"currency"]], rows };
}

function consumerHistory(database,_reportMonths,_billMonth,connStatus='all') {
  const regularJoin=connStatus==='all'?'':` INNER JOIN master m ON m.Code=h.Code AND m.ConnStatus='${connStatus}'`,individualJoin=connStatus==='all'?'':` INNER JOIN master_bi mi ON mi.Code=h.Code AND mi.ConnStatus='${connStatus}'`;
  const statement=`SELECT billmonth,area,book,address,SUM(cnt),SUM(kwh),SUM(bill) FROM (SELECT h.billmonth,h.Area area,h.Book book,COALESCE(a.AreaName,'') address,COUNT(h.entry) cnt,COALESCE(SUM(h.KilowattHour),0) kwh,COALESCE(SUM(h.TotalBill),0) bill FROM billhistory h LEFT JOIN tblarea a ON a.AreaCode=h.Area AND a.AreaBook=h.Book${regularJoin} WHERE h.billmonth IN (${monthList}) AND COALESCE(h.ratecode,'')<>'B' GROUP BY h.billmonth,h.Area,h.Book,a.AreaName UNION ALL SELECT h.billmonth,h.Area,h.Book,COALESCE(a.AreaName,''),COUNT(h.entry),COALESCE(SUM(h.KilowattHour),0),COALESCE(SUM(h.TotalBill),0) FROM billhistory_bi h LEFT JOIN tblarea a ON a.AreaCode=h.Area AND a.AreaBook=h.Book${individualJoin} WHERE h.billmonth IN (${monthList}) AND COALESCE(h.ratecode,'')='B' GROUP BY h.billmonth,h.Area,h.Book,a.AreaName) x GROUP BY billmonth,area,book,address ORDER BY billmonth DESC,area,book,address;`;
  const rows=parse(sql(database,statement),["month","area","book","address","consumers","kwh","totalBill"]).map((r)=>num(r,["consumers","kwh","totalBill"]));
  return { columns:[["month","Month","month"],["area","Area","text"],["book","Book","text"],["address","Address","text"],["consumers","Consumers","number"],["kwh","kWh","decimal"],["totalBill","Total bill","currency"]], metrics:[["Address groups",rows.length,"number"],["Consumers",rows.reduce((s,r)=>s+r.consumers,0),"number"],["kWh",rows.reduce((s,r)=>s+r.kwh,0),"decimal"],["Total billed",rows.reduce((s,r)=>s+r.totalBill,0),"currency"]], rows };
}
async function combinedHistory(_database,_reportMonths,billMonth) {
  const selectedMonthList=billMonth?`'${billMonth}'`:monthList;
  const groups = await Promise.all(databases.map(async ({ database, label }) => {
    const statement = `SELECT source,billmonth,SUM(consumers),SUM(kwh),SUM(total_bill) FROM (SELECT 'billhistory' source,billmonth,COUNT(entry) consumers,COALESCE(SUM(KilowattHour),0) kwh,COALESCE(SUM(TotalBill),0) total_bill FROM billhistory WHERE billmonth IN (${selectedMonthList}) GROUP BY billmonth UNION ALL SELECT 'billhistory_bi',billmonth,COUNT(entry),COALESCE(SUM(KilowattHour),0),COALESCE(SUM(TotalBill),0) FROM billhistory_bi WHERE billmonth IN (${selectedMonthList}) GROUP BY billmonth) x GROUP BY source,billmonth ORDER BY billmonth DESC,source;`;
    const databaseRows = parse(await sqlAsync(database, statement), ["table", "month", "consumers", "kwh", "totalBill"]).map((row) => num(row, ["consumers", "kwh", "totalBill"]));
    return databaseRows.map((row) => ({ database: label, ...row }));
  }));
  const rows = groups.flat();
  return {
    columns: [["database","Database","text"],["table","Source table","text"],["month","Month","month"],["consumers","Consumers","number"],["kwh","kWh","decimal"],["totalBill","Total bill","currency"]],
    metrics: [["Databases",databases.length,"number"],["Consumer records",rows.reduce((sum,row)=>sum+row.consumers,0),"number"],["Total kWh",rows.reduce((sum,row)=>sum+row.kwh,0),"decimal"],["Total billed",rows.reduce((sum,row)=>sum+row.totalBill,0),"currency"]],
    rows,
  };
}
