async function buildMonthCatalog(){
  const found=await Promise.all(databases.map(async({database})=>{const statement="SELECT BillMonth FROM billhistory WHERE BillMonth REGEXP '^[0-9][0-9][0-9][0-9]$' AND LEFT(BillMonth,2) BETWEEN '01' AND '12' GROUP BY BillMonth UNION SELECT BillMonth FROM billhistory_bm WHERE BillMonth REGEXP '^[0-9][0-9][0-9][0-9]$' AND LEFT(BillMonth,2) BETWEEN '01' AND '12' GROUP BY BillMonth UNION SELECT BillMonth FROM billhistory_bi WHERE BillMonth REGEXP '^[0-9][0-9][0-9][0-9]$' AND LEFT(BillMonth,2) BETWEEN '01' AND '12' GROUP BY BillMonth;";return(await sqlAsync(database,statement)).split(/\r?\n/).filter(Boolean)}));
  const all=[...new Set([...months,...found.flat()])].sort((a,b)=>Number(b.slice(2))-Number(a.slice(2))||Number(b.slice(0,2))-Number(a.slice(0,2))),payload={generatedAt:new Date().toISOString(),months:all};
  monthCatalogMemory=payload;writePortableCache("bill-months-v2","month-catalog",payload);return{...payload,cached:false,storage:"sqlite",offline:false};
}
async function getMonthCatalog(forceRefresh=false){
  if(forceRefresh)return buildMonthCatalog();
  const cached=monthCatalogMemory??readPortableCache("bill-months-v2");
  if(cached){monthCatalogMemory=cached;const stale=Date.now()-Date.parse(cached.generatedAt)>monthCatalogTtlMs;if(stale)setImmediate(()=>buildMonthCatalog().catch(console.error));return{...cached,cached:true,refreshing:stale,storage:"sqlite",offline:false}}
  try{return await buildMonthCatalog()}catch(error){console.error(error);return{generatedAt:new Date().toISOString(),months,warning:"Live month catalog unavailable; configured months shown.",cached:false,storage:"memory",offline:true}}
}
