function bankName(username,fullName){
  const text=`${username} ${fullName}`.toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
  if(/\becpay\b/.test(text))return"ECPAY";
  if(/\bdbp\b/.test(text))return text.includes("gcash")?"DBP - GCASH":"DBP";
  if(/\bland ?bank\b|^lb\b/.test(text))return"LAND BANK";
  if(/\bbdo\b/.test(text))return"BDO";
  if(/\bmetro ?bank\b/.test(text))return"METROBANK";
  if(/\bpnb\b/.test(text))return"PNB";
  if(/\baub\b|asia united bank/.test(text))return"AUB";
  if(/\bpbb\b/.test(text))return"PBB";
  if(/\bfcb\b|first consolidated bank/.test(text))return"FIRST CONSOLIDATED BANK";
  return null;
}
