async function netMeteringReport(database,billMonth=''){
  const selected=database==='all'?databases:databases.filter(item=>item.database===database);
  if(!selected.length)throw new Error('Invalid office');
  const monthCondition=billMonth?` WHERE bh.BillMonth='${billMonth}'`:'';
  const statement=`SELECT bh.Entry,bh.Code,bh.AccountNumber,bh.Name,bh.Address,bh.Area,bh.Book,bh.Sequence,bh.RateCode,bh.Grid,bh.BillMonth,bh.PreviousReadingDate,bh.PresentReadingDate,bh.PresentReadingKWH,bh.PreviousReadingKWH,bh.Multiplier,bh.KilowattHour,bh.PresentReadingKWHout,bh.PreviousReadingKWHout,bh.KilowattHourOut,bh.TotalBill,bh.PreviousMonthCredit,bh.GenSysChargeOut,bh.GrandTotal,bh.flag_paid,bh.date_paid,COALESCE(m.ConnStatus,''),COALESCE(m.Serial,bh.Serial),COALESCE(m.Name,bh.Name),COALESCE(m.Address,bh.Address) FROM billhistory_net bh LEFT JOIN master_net m ON m.Code=bh.Code${monthCondition} ORDER BY CAST(CONCAT('20',RIGHT(bh.BillMonth,2),LEFT(bh.BillMonth,2)) AS UNSIGNED) DESC,bh.Area,bh.Book,bh.Sequence,bh.AccountNumber`;
  const keys=['entry','code','accountNumber','billName','billAddress','area','book','sequence','rateCode','grid','billMonth','previousReadingDate','presentReadingDate','presentReading','previousReading','multiplier','importKwh','presentExportReading','previousExportReading','exportKwh','incomingBill','previousMonthCredit','exportRate','grandTotal','paidFlag','paidDate','connectionStatus','serial','name','address'];
  const groups=await Promise.all(selected.map(async office=>parse(await sqlAsync(office.database,statement),keys).map(row=>{
    num(row,['entry','code','multiplier','presentReading','previousReading','importKwh','presentExportReading','previousExportReading','exportKwh','incomingBill','previousMonthCredit','exportRate','grandTotal']);
    const priorCredit=Math.min(0,row.previousMonthCredit||0),exportCredit=(row.exportKwh||0)*(row.exportRate||0),computedGrandTotal=(row.incomingBill||0)-exportCredit+priorCredit;
    return{...row,office:office.label,officeDatabase:office.database,priorCredit,exportCredit,computedGrandTotal,variance:(row.grandTotal||0)-computedGrandTotal,paid:String(row.paidFlag||'').toUpperCase()==='Y'};
  })));
  const rows=groups.flat(),sum=field=>rows.reduce((total,row)=>total+Number(row[field]||0),0),monthsAvailable=[...new Set(rows.map(row=>row.billMonth).filter(Boolean))].sort((a,b)=>String(b).slice(2).localeCompare(String(a).slice(2))||String(b).slice(0,2).localeCompare(String(a).slice(0,2)));
  return{generatedAt:new Date().toISOString(),database,billMonth,rows,months:monthsAvailable,totals:{consumers:rows.length,importKwh:sum('importKwh'),exportKwh:sum('exportKwh'),incomingBill:sum('incomingBill'),exportCredit:sum('exportCredit'),previousCredit:sum('priorCredit'),grandTotal:sum('grandTotal'),computedGrandTotal:sum('computedGrandTotal'),variance:sum('variance')}};
}

const netRatePrefixes={R:'Res',C:'Com',I:'Ind',P:'Pub',S:'Str',H:'CHV',V:'PHV'};
const netBillComponents=[
  ['GenSysCharge','Generation charge','GenSysCharge','kwh'],['PowerActRateRed','Power Act reduction','PowerActRateRed','kwh'],['TCDemandCharge','Transmission demand','TCDemandCharge','demand'],['TCTransSystemCharge','Transmission system','TCTransSystemCharge','kwh'],['SystemLossCharge','System loss','SystemLossCharge','kwh'],['DCDemandCharge','Distribution demand','DCDemandCharge','demand'],['DCDistributionCharge','Distribution system','DCDistributionCharge','kwh'],['SCRetCustCharge','Supply retail','SCRetCustCharge','fixed'],['SCSupplySysCharge','Supply system','SCSupplySysCharge','kwh'],['MCRetailCustCharge','Metering retail','MCRetailCustCharge','fixed'],['MCSystemCharge','Metering system','MCSystemCharge','kwh'],['UCNPCStrandedDebts','NPC stranded debt','UCNPCStrandedDebts','kwh'],['UCNPCStrandedContCost','NPC stranded cost','UCNPCStrandedContCost','kwh'],['UCME','Missionary electrification','UCME','kwh'],['UCME_Redci','Missionary RED-CI','UCME_Redci','kwh'],['UCEC','Environmental charge','UCEC','kwh'],['FitAll','FIT-All','FitAll','kwh'],['MCC','Reinvestment fund / MCC','MCC','kwh'],['MCC_Substation','MCC substation','MCC_Substation','kwh'],['ICCrossSubsidyCharge','Inter-class cross subsidy','ICCrossSubsidyCharge','kwh'],['RPPD','RPPD','RPPD','kwh'],['ICCS','ICCS','ICCS','kwh'],['TrueUp','True-up','TrueUp','kwh'],['RealPropertyTax','Real property tax','RealPropertyTax','kwh'],['LifelineCollect','Lifeline collection','LifelineCollect','kwh'],['senior_citizen_subsidy','Senior citizen subsidy','Senior_Subsidy','kwh'],['EVAT_GenCharge','VAT – generation','GenCharge','kwh'],['EVAT_Trans_Charge','VAT – transmission','Trans_Charge','kwh'],['EVAT_SystemLoss','VAT – system loss','SystemLoss','kwh'],['EVAT_Dist_Charge','VAT – distribution','Dist_Charge','kwh'],['EVAT_OtherVat','VAT – other','OtherVat','kwh']
];
async function netMeteringConsumers(database){
  if(!allowed.has(database))throw new Error('Select one office.');
  const statement="SELECT Code,AccountNumber,Name,Address,Area,Book,Sequence,RateCode,Grid,Serial,Multiplier,Reading_KWH,outkwh_prev,LastReadingDate,ConnStatus FROM master_net ORDER BY Area,Book,Sequence,AccountNumber";
  return parse(await sqlAsync(database,statement),['code','accountNumber','name','address','area','book','sequence','rateCode','grid','serial','multiplier','previousImportReading','previousExportReading','lastReadingDate','connectionStatus']).map(row=>num(row,['code','grid','multiplier','previousImportReading','previousExportReading']));
}
async function calculateNetMeteringBill(database,input){
  if(!allowed.has(database))throw new Error('Select one office.');
  const code=Number(input.code),billMonth=String(input.billMonth||''),presentReading=Number(input.presentReading),presentExportReading=Number(input.presentExportReading),demand=Number(input.demand||0),previousReadingDate=String(input.previousReadingDate||''),presentReadingDate=String(input.presentReadingDate||'');
  if(!Number.isInteger(code)||code<1||!/^(0[1-9]|1[0-2])\d{2}$/.test(billMonth)||![presentReading,presentExportReading,demand].every(Number.isFinite)||presentReading<0||presentExportReading<0||demand<0||!/^\d{4}-\d{2}-\d{2}$/.test(previousReadingDate)||!/^\d{4}-\d{2}-\d{2}$/.test(presentReadingDate)||previousReadingDate>presentReadingDate)throw new Error('Check the consumer, bill month, readings, demand, and reading dates.');
  const consumers=await netMeteringConsumers(database),consumer=consumers.find(row=>row.code===code);if(!consumer)throw new Error('Net-metering consumer was not found.');
  const prefix=netRatePrefixes[String(consumer.rateCode||'').toUpperCase()];if(!prefix)throw new Error(`Rate code ${consumer.rateCode||'(blank)'} is not supported for bill creation.`);
  const rateColumns=[...new Set(netBillComponents.map(item=>`${prefix}_${item[2]}`).concat(`${prefix}_GenSysCharge`))],rateOutput=await sqlAsync(database,`SELECT ${rateColumns.join(',')} FROM tblERC WHERE BillMonth='${billMonth}' AND Grid=${Number(consumer.grid)||1} LIMIT 1`);if(!rateOutput)throw new Error(`No approved tblERC rate was found for ${billMonth}, Grid ${consumer.grid}, Rate ${consumer.rateCode}.`);
  const rates=parse(rateOutput,rateColumns)[0],multiplier=Number(consumer.multiplier)||1,previousReading=Number(consumer.previousImportReading)||0,previousExportReading=Number(consumer.previousExportReading)||0,importKwh=Math.max(0,(presentReading-previousReading)*multiplier),exportKwh=Math.max(0,(presentExportReading-previousExportReading)*multiplier);
  const components=netBillComponents.map(([field,label,rateField,basis])=>{const rate=Number(rates[`${prefix}_${rateField}`]||0),quantity=basis==='fixed'?1:basis==='demand'?demand*multiplier:importKwh,amount=quantity*rate;return{field,label,rate,basis,quantity,amount}}),incomingBill=components.reduce((sum,item)=>sum+item.amount,0),exportRate=Number(rates[`${prefix}_GenSysCharge`]||0),exportCredit=exportKwh*exportRate;
  const priorOutput=await sqlAsync(database,`SELECT GrandTotal FROM billhistory_net WHERE Code=${code} AND BillMonth<>'${billMonth}' ORDER BY CAST(CONCAT('20',RIGHT(BillMonth,2),LEFT(BillMonth,2)) AS UNSIGNED) DESC,Entry DESC LIMIT 1`),previousMonthCredit=Math.min(0,Number(priorOutput||0)),grandTotal=incomingBill-exportCredit+previousMonthCredit;
  return{database,consumer,billMonth,previousReadingDate,presentReadingDate,previousReading,presentReading,previousExportReading,presentExportReading,multiplier,demand,importKwh,exportKwh,components,incomingBill,exportRate,exportCredit,previousMonthCredit,grandTotal};
}
async function saveNetMeteringBill(database,input){
  const bill=await calculateNetMeteringBill(database,input),duplicate=Number(await sqlAsync(database,`SELECT COUNT(*) FROM billhistory_net WHERE Code=${bill.consumer.code} AND BillMonth='${bill.billMonth}'`));if(duplicate)throw new Error('A net-metering bill already exists for this consumer and bill month.');
  const values={Code:bill.consumer.code,Area:bill.consumer.area,Book:bill.consumer.book,Sequence:bill.consumer.sequence,AccountNumber:bill.consumer.accountNumber,Name:bill.consumer.name,Address:bill.consumer.address,RateCode:bill.consumer.rateCode,Serial:bill.consumer.serial,Multiplier:bill.multiplier,PreviousReadingDate:bill.previousReadingDate,PresentReadingDate:bill.presentReadingDate,PresentReadingKWH:bill.presentReading,PreviousReadingKWH:bill.previousReading,Diff:bill.presentReading-bill.previousReading,Demand:bill.demand,KilowattHour:bill.importKwh,KilowattUsed:bill.importKwh,TotalBill:bill.incomingBill,BillMonth:bill.billMonth,Grid:bill.consumer.grid,PresentReadingKWHout:bill.presentExportReading,PreviousReadingKWHout:bill.previousExportReading,DiffOut:bill.presentExportReading-bill.previousExportReading,KilowattHourOut:bill.exportKwh,KilowattUsedOut:String(bill.exportKwh),PreviousMonthCredit:bill.previousMonthCredit,GenSysChargeOut:bill.exportRate,GrandTotal:bill.grandTotal,flag_paid:'N'};for(const component of bill.components)values[component.field]=component.amount;
  const columns=Object.keys(values),sqlValue=value=>typeof value==='number'?(Number.isFinite(value)?String(value):'0'):`'${escapeSql(String(value??''))}'`,statement=`INSERT INTO billhistory_net (${columns.map(column=>`\`${column}\``).join(',')}) VALUES (${columns.map(column=>sqlValue(values[column])).join(',')}); SELECT LAST_INSERT_ID();`;
  const output=await sqlAsync(database,statement),entry=Number(String(output).trim().split(/\s+/).at(-1));return{ok:true,entry,bill};
}

const itDataColumns=['Id','usercode','name','position','department','privilage','username','mobile_number','VL','SL','OL','OT','SLbal','OLbal','employmentdate','bioUID','privilagemenu','address','emailadd','area','basic','VLbal','profile_photo_mime','profile_photo_updated_at','registration_pending','SG'];
async function itDataReport(params){
  const connection=itProgramConnection;
  if(!connection.enabled)throw new Error('Enable the optional IT Program connection in Database Settings first.');
  if(!/^[A-Za-z0-9_]{1,64}$/.test(connection.database))throw new Error('Check the IT Program database name in Settings.');
  const search=(params.get('search')??'').trim();
  if(search.length>128)throw new Error('Search must be 128 characters or fewer.');
  const page=Math.min(1000000,Math.max(1,Math.floor(Number(params.get('page')))||1)),pageSize=50;
  const args=['-h',connection.host,'-P',String(connection.port),'-u',connection.user,...(connection.password?[`-p${connection.password}`]:[]),'-N','-B',connection.database];
  const literal=search?`CONVERT(0x${Buffer.from(search,'utf8').toString('hex')} USING utf8)`:'';
  const where=search?` WHERE ${itDataColumns.map(column=>`LOCATE(LOWER(${literal}),LOWER(COALESCE(CAST(\`${column}\` AS CHAR),'')))>0`).join(' OR ')}`:'';
  const total=Number((await mysqlFromStdin(connection.executable,args,`SELECT COUNT(*) FROM usertb${where};`)).trim());
  const pages=Math.max(1,Math.ceil(total/pageSize)),currentPage=Math.min(page,pages);
  const select=itDataColumns.map(column=>`HEX(CAST(\`${column}\` AS CHAR))`).join(',');
  const output=await mysqlFromStdin(connection.executable,args,`SELECT ${select} FROM usertb${where} ORDER BY Id LIMIT ${pageSize} OFFSET ${(currentPage-1)*pageSize};`);
  const rowOutput=output.replace(/[\r\n]+$/,'');
  const rows=rowOutput?rowOutput.split(/\r?\n/).map(line=>line.split('\t').map(value=>value==='NULL'?null:Buffer.from(value,'hex').toString('utf8'))):[];
  return{database:connection.database,table:'usertb',columns:itDataColumns,rows,total,page:currentPage,pageSize,pages,search};
}

function workspaceConnections(){return[
  {id:'billing',label:'Billing',enabled:true,host:mysqlHost,port:mysqlPort||3306,user:mysqlUser,password:mysqlPassword,executable:mysqlExe,database:databases[0]?.database},
  {id:'membership',label:'Membership',enabled:true,host:membershipHost,port:membershipPort||3306,user:membershipUser,password:membershipPassword,executable:membershipExe,database:membershipDatabase.database},
  {id:'ecpayAudit',label:'ECPay Audit',enabled:auditEnabled,host:auditHost,port:auditPort,user:auditUser,password:auditPassword,executable:auditExe,database:ecpayAuditDatabase},
  {id:'itProgram',label:'IT Program',...itProgramConnection}
]}
function workspaceConnection(id='itProgram'){
  const c=workspaceConnections().find(item=>item.id===id);
  if(!c)throw new Error('Choose a configured connection.');
  if(!c.enabled)throw new Error(`Enable the ${c.label} connection in Database Settings first.`);
  return c;
}
async function workspaceSql(statement,database,connection='itProgram'){
  const c=workspaceConnection(connection);database??=c.database;
  if(typeof database!=='string'||!database||database.length>64||database.startsWith('-')||/[\x00-\x1f]/.test(database))throw new Error('Choose a valid database.');
  const args=['-h',c.host,'-P',String(c.port),'-u',c.user,...(c.password?[`-p${c.password}`]:[]),'--batch','--default-character-set=utf8mb4',database];
  return parseWorkspaceOutput(await mysqlFromStdin(c.executable,args,statement,20000));
}
async function workspaceDatabases(connection='itProgram'){
  const c=workspaceConnection(connection),data=await workspaceSql("SHOW DATABASES;",'information_schema',connection);
  return{connection,defaultDatabase:c.database,databases:data.rows.map(row=>row[0])};
}
async function workspaceSchema(database,connection='itProgram'){
  database??=workspaceConnection(connection).database;
  const data=await workspaceSql("SELECT TABLE_NAME,COLUMN_NAME,DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME,ORDINAL_POSITION;",database,connection);
  const tables=new Map();for(const [table,name,type] of data.rows){if(!tables.has(table))tables.set(table,{name:table,columns:[]});tables.get(table).columns.push({name,type})}
  return{connection,database,tables:[...tables.values()]};
}
const workspacePreviews=new Map();
function workspaceFingerprint(connection){return createHash('sha256').update(JSON.stringify(workspaceConnection(connection))).digest('hex')}
function previewWorkspaceQuery(input){
  const connection=input.connection??'itProgram',c=workspaceConnection(connection),database=input.database??c.database,query=validateWorkspaceQuery(input.query);
  if(typeof database!=='string'||!database||database.length>64||database.startsWith('-')||/[\x00-\x1f]/.test(database))throw new Error('Choose a valid database.');
  const now=Date.now();for(const [key,value] of workspacePreviews)if(value.expires<=now)workspacePreviews.delete(key);
  if(workspacePreviews.size>=1000)workspacePreviews.delete(workspacePreviews.keys().next().value);
  const token=randomUUID(),expires=now+5*60*1000;
  workspacePreviews.set(token,{connection,database,query,expires,fingerprint:workspaceFingerprint(connection)});
  return{token,connection,database,query,limit:500,expiresAt:new Date(expires).toISOString()};
}
function consumeWorkspacePreview(input){
  const value=workspacePreviews.get(input.previewToken);
  if(!value||value.expires<=Date.now())throw new Error('Preview the query first. Previews expire after five minutes.');
  if(value.connection!==(input.connection??'itProgram')||value.database!==input.database||value.query!==validateWorkspaceQuery(input.query)||value.fingerprint!==workspaceFingerprint(value.connection))throw new Error('The query or connection changed. Preview it again before running.');
  workspacePreviews.delete(input.previewToken);return value;
}
async function workspaceQuery(value,database,connection='itProgram'){
  database??=workspaceConnection(connection).database;
  const query=validateWorkspaceQuery(value),start=Date.now();
  const result=await workspaceSql(`SELECT * FROM (${query}) AS workspace_result LIMIT 501;`,database,connection);
  return{...result,connection,database,rows:result.rows.slice(0,500),truncated:result.rows.length>500,limit:500,durationMs:Date.now()-start};
}

