async function discoReport(f) {
  const selected=f.database==='all'?databases:databases.filter(d=>d.database===f.database);
  const suffix={regular:'',individual:'_bi',mother:'_bm'}[f.source];
  const groups=await Promise.all(selected.map(async office=>{
    const location=[f.area?`x.Area='${f.area}'`:'',f.book?`x.Book='${f.book}'`:''].filter(Boolean);
    let statement;
    if(['unpaid-disconnected','unpaid-still'].includes(f.mode)){
      const still=f.mode==='unpaid-still';
      const range=`Date >= '${f.from}' AND Date < DATE_ADD('${f.to}', INTERVAL 1 DAY)`;
      // Group event dates before joining bills to avoid multiplying unpaid balances.
      statement=`SELECT x.Code,x.AccountNumber,x.Name,x.Address,x.Area,x.Book,ld.DisconnectionDate,lr.ReconnectionDate,x.BillMonth,x.KilowattHour,x.TotalBill,m.ConnStatus FROM billhistory${suffix} x ${still?'INNER':'LEFT'} JOIN master${suffix} m ON m.Code=x.Code INNER JOIN (SELECT Code,MAX(Date) AS DisconnectionDate FROM disconnection${suffix} ${still?'':`WHERE ${range}`} GROUP BY Code) ld ON ld.Code=x.Code LEFT JOIN (SELECT Code,MAX(Date) AS ReconnectionDate FROM reconnection${suffix} GROUP BY Code) lr ON lr.Code=x.Code WHERE UPPER(TRIM(IFNULL(x.flag_paid,''))) <> 'Y' AND IFNULL(x.TotalBill,0)>0 ${still?`AND ld.DisconnectionDate >= '${f.from}' AND ld.DisconnectionDate < DATE_ADD('${f.to}', INTERVAL 1 DAY) AND (lr.ReconnectionDate IS NULL OR lr.ReconnectionDate < ld.DisconnectionDate)`:''} ${location.map(c=>' AND '+c).join('')} ORDER BY ld.DisconnectionDate,x.AccountNumber,CONCAT('20',RIGHT(x.BillMonth,2),LEFT(x.BillMonth,2))`;
      return parse(await sqlAsync(office.database,statement),['code','account','name','address','area','book','date','reconnectionDate','billMonth','kwh','totalBill','status']).map(row=>({...num(row,['kwh','totalBill']),office:office.label,accountStatus:still?'STILL DISCONNECTED':'Disconnected during selected period'}));
    }
    if(f.mode==='long'){
      statement=`SELECT x.Code,x.AccountNumber,x.Name,x.Address,x.Area,x.Book,x.DisconnectionDate,x.ConnStatus,DATEDIFF(CURDATE(),x.DisconnectionDate) FROM master${suffix} x WHERE x.ConnStatus='D' AND x.DisconnectionDate>'0000-00-00' AND DATEDIFF(CURDATE(),x.DisconnectionDate)>=${f.days} ${location.map(c=>' AND '+c).join('')} ORDER BY x.DisconnectionDate,x.Area,x.Book`;
    }else{
      const table=f.mode==='disconnected'?'disconnection':'reconnection';
      statement=`SELECT x.Code,x.AccountNumber,x.Name,COALESCE(m.Address,''),x.Area,x.Book,x.Date,COALESCE(m.ConnStatus,''),NULL FROM ${table}${suffix} x LEFT JOIN master${suffix} m ON m.Code=x.Code WHERE x.Date BETWEEN '${f.from}' AND '${f.to}' ${location.map(c=>' AND '+c).join('')} ORDER BY x.Date,x.Area,x.Book`;
    }
    return parse(await sqlAsync(office.database,statement),['code','account','name','address','area','book','date','status','days']).map(row=>({...row,office:office.label,days:row.days===''?null:Number(row.days)}));
  }));
  return {rows:groups.flat(),filters:f,generatedAt:new Date().toISOString()};
}
